    private fun parseRoutes(encoded: String): Map<Int, List<String>> =
        encoded.split('|').associate { entry ->
            val eq = entry.indexOf('=')
            entry.substring(0, eq).toInt() to entry.substring(eq + 1).split(',')
        }

