        OutRule.DOUBLE to parseRoutes(ROUTES_DOUBLE),
        OutRule.MASTER to parseRoutes(ROUTES_MASTER),
        OutRule.STRAIGHT to parseRoutes(ROUTES_STRAIGHT),
    )

    /** The route THRØ shows for `remaining`, or null when there is no finish. */
    public fun route(remaining: Int, outRule: OutRule): List<String>? =
        ROUTE_TABLES.getValue(outRule)[remaining]

