    private fun opening(max: Int, unopenable: IntArray): Set<Int> {
        val bad = unopenable.toHashSet()
        val out = HashSet<Int>(max)
        for (v in 1..max) if (v !in bad && v !in IMPOSSIBLE_VISIT_TOTALS) out.add(v)
        return out
    }

    /** The floor is the rule's own: under straight-out a single 1 finishes. */
    private fun build(min: Int, max: Int, bogeys: IntArray): Set<Int> {
        val bad = bogeys.toHashSet()
        val out = HashSet<Int>(max)
        for (v in min..max) if (v !in bad) out.add(v)
        return out
    }
